'use strict';
/* Organisation et autorisations locales de démonstration, sans authentification serveur. */
const ORG_KEY='rg-demo-organizations-v1';
const ORG_FEATURES=[['societe','Informations de la société'],['associes','Associés et comptes'],['titres','Mouvements de titres'],['decisions','Décisions'],['custom-decisions','Registres sur mesure'],['personnel','Personnel et annexes'],['documents','Documents sociaux'],['depot','Dépôt des comptes'],['annonces','Annonces légales'],['procedures','Suivi des formalités'],['certifications','Certifications'],['utilisateurs','Personnes et droits de la société'],['facturation','Licence et facturation'],['preferences','Préférences']];
const ORG_PLANS=[{id:'unassigned',name:'À attribuer',price:null,certifications:null},{id:'conservation',name:'Conservation',price:8,certifications:0},{id:'acces',name:'Accès',price:49,certifications:3},{id:'premium',name:'Premium',price:99,certifications:15},{id:'illimite',name:'Illimité',price:299,certifications:'Illimité'},{id:'carnet',name:'Carnet historique',price:null,certifications:5}];
let organizationWorkspace=null;
const orgUI={tab:'portfolio',query:'',plan:'all',responsible:'all',page:1,selected:new Set(),pickerPage:1,pickerQuery:'',peopleQuery:'',peoplePage:1,inspectorPerson:'me',inspectorCompany:'',inspectorFeature:'titres'};
function orgPlan(id){return ORG_PLANS.find(p=>p.id===id)||ORG_PLANS[0];}
function orgPermissionMap(level){return Object.fromEntries(ORG_FEATURES.map(([id])=>[id,level]));}
function orgDefaultRoles(){return[{id:'group-admin',name:'Administrateur du groupe',management:'group',permissions:orgPermissionMap('none'),protected:true},{id:'cabinet-admin',name:'Administrateur de cabinet',management:'cabinet',permissions:orgPermissionMap('none'),protected:true},{id:'legal-manager',name:'Gestion juridique',management:'none',permissions:orgPermissionMap('write'),protected:true},{id:'legal-reader',name:'Consultation juridique',management:'none',permissions:orgPermissionMap('read'),protected:true}];}
function normalizeOrganizations(value){
 if(!value||value.version!==1)return null;
 const text=(v,max=180)=>typeof v==='string'?v.trim().slice(0,max):'',id=v=>typeof v==='string'&&/^[a-zA-Z0-9_-]{1,100}$/.test(v);
 const unique=(list,convert,limit)=>{const rows=[];for(const item of (Array.isArray(list)?list:[]).slice(0,limit)){const row=convert(item||{});if(row&&id(row.id)&&!rows.some(x=>x.id===row.id))rows.push(row);}return rows;};
 const groups=unique(value.groups,r=>text(r.name)?{id:r.id,name:text(r.name,100),description:text(r.description,240)}:null,100);
 const cabinets=unique(value.cabinets,r=>groups.some(g=>g.id===r.groupId)&&text(r.name)?{id:r.id,groupId:r.groupId,name:text(r.name,100),city:text(r.city,120)}:null,500);
 if(!groups.length||!cabinets.length)return null;
 const people=unique(value.people,r=>text(r.name)?{id:r.id,name:text(r.name,120),email:text(r.email,150)}:null,2000);
 if(!people.some(p=>p.id==='me'))people.unshift({id:'me',name:'Votre compte',email:''});
 const roles=[...orgDefaultRoles(),...unique((Array.isArray(value.roles)?value.roles:[]).filter(r=>!orgDefaultRoles().some(role=>role.id===r?.id)),r=>!orgDefaultRoles().some(x=>x.id===r.id)&&text(r.name)?{id:r.id,name:text(r.name,80),groupId:groups.some(g=>g.id===r.groupId)?r.groupId:groups[0].id,management:['group','cabinet'].includes(r.management)?r.management:'none',permissions:Object.fromEntries(ORG_FEATURES.map(([key])=>[key,['read','write'].includes(r.permissions?.[key])?r.permissions[key]:'none'])),protected:false}:null,100)];
 const links=[];for(const r of (Array.isArray(value.links)?value.links:[]).slice(0,1000)){if(!id(r?.companyId)||!cabinets.some(c=>c.id===r.cabinetId)||links.some(x=>x.companyId===r.companyId))continue;links.push({companyId:r.companyId,cabinetId:r.cabinetId,plan:orgPlan(r.plan).id,payer:['cabinet','company'].includes(r.payer)?r.payer:'group',responsibles:[...new Set((Array.isArray(r.responsibles)?r.responsibles:[]).filter(id=>people.some(p=>p.id===id)))]});}
 const assignments=unique(value.assignments,r=>people.some(p=>p.id===r.personId)&&roles.some(p=>p.id===r.roleId)&&((r.scope==='group'&&groups.some(g=>g.id===r.scopeId))||(r.scope==='cabinet'&&cabinets.some(c=>c.id===r.scopeId))||(r.scope==='company'&&links.some(c=>c.companyId===r.scopeId)))?{id:r.id,personId:r.personId,roleId:r.roleId,scope:r.scope,scopeId:r.scopeId,protected:r.protected===true&&r.personId==='me'&&r.roleId==='group-admin'&&r.scope==='group'}:null,5000);
 const delegations=unique(value.delegations,r=>{const link=links.find(l=>l.companyId===r.companyId),from=cabinets.find(c=>c.id===link?.cabinetId),to=cabinets.find(c=>c.id===r.cabinetId);return from&&to&&from.groupId===to.groupId&&from.id!==to.id?{id:r.id,companyId:r.companyId,cabinetId:r.cabinetId,level:r.level==='write'?'write':'read'}:null;},3000);
 const context={groupId:groups.some(g=>g.id===value.context?.groupId)?value.context.groupId:groups[0].id,cabinetId:'all'};if(cabinets.some(c=>c.id===value.context?.cabinetId&&c.groupId===context.groupId))context.cabinetId=value.context.cabinetId;
 const validAssignments=assignments.filter(a=>{const role=roles.find(r=>r.id===a.roleId),gid=a.scope==='group'?a.scopeId:a.scope==='cabinet'?cabinets.find(c=>c.id===a.scopeId)?.groupId:cabinets.find(c=>c.id===links.find(l=>l.companyId===a.scopeId)?.cabinetId)?.groupId;return(!role.groupId||role.groupId===gid)&&(role.management==='none'||role.management===a.scope);});return{version:1,groups,cabinets,people,roles,links,assignments:validAssignments,delegations,context};
}
function initializeOrganizations(entries,account){
 try{organizationWorkspace=normalizeOrganizations(JSON.parse(localStorage.getItem(ORG_KEY)));}catch{}
 if(!organizationWorkspace){organizationWorkspace={version:1,groups:[{id:'g-novea',name:'Groupe Novéa',description:'Groupe de démonstration · cabinets indépendants, portefeuille commun.'},{id:'g-horizon',name:'Groupe Horizon',description:'Un second groupe pour vérifier la séparation des périmètres.'}],cabinets:[{id:'c-paris',groupId:'g-novea',name:'Cabinet Paris',city:'Paris'},{id:'c-lyon',groupId:'g-novea',name:'Cabinet Lyon',city:'Lyon'},{id:'c-nantes',groupId:'g-novea',name:'Cabinet Nantes',city:'Nantes'},{id:'c-bordeaux',groupId:'g-horizon',name:'Cabinet Bordeaux',city:'Bordeaux'}],people:[{id:'me',name:[account.firstname,account.lastname].filter(Boolean).join(' ')||'Votre compte',email:account.email||''},{id:'lea',name:'Léa Martin',email:'lea.martin@example.test'},{id:'hugo',name:'Hugo Bernard',email:'hugo.bernard@example.test'},{id:'camille',name:'Camille Moreau',email:'camille.moreau@example.test'},{id:'alex',name:'Alex Laurent',email:'alex.laurent@example.test'}],roles:orgDefaultRoles(),links:[],assignments:[],delegations:[],context:{groupId:'g-novea',cabinetId:'all'}};
 for(const group of organizationWorkspace.groups)for(const roleId of ['group-admin','legal-manager'])organizationWorkspace.assignments.push({id:group.id+'-'+roleId,personId:'me',roleId,scope:'group',scopeId:group.id,protected:roleId==='group-admin'});
 organizationWorkspace.assignments.push({id:'lea-admin-paris',personId:'lea',roleId:'cabinet-admin',scope:'cabinet',scopeId:'c-paris'},{id:'lea-reader-lyon',personId:'lea',roleId:'legal-reader',scope:'cabinet',scopeId:'c-lyon'},{id:'hugo-admin-lyon',personId:'hugo',roleId:'cabinet-admin',scope:'cabinet',scopeId:'c-lyon'},{id:'hugo-legal-lyon',personId:'hugo',roleId:'legal-manager',scope:'cabinet',scopeId:'c-lyon'});
 entries.forEach((entry,i)=>{const demo=entry.example||entry.demoFixture||entry.volumeDemo,cabinetId=!demo?'c-paris':i<4?'c-paris':i<7?'c-lyon':i<9?'c-nantes':'c-bordeaux';organizationWorkspace.links.push({companyId:entry.id,cabinetId,plan:entry.example?'carnet':entry.demoFixture?['acces','premium','illimite'][i%3]:'unassigned',payer:'group',responsibles:demo?[i<4?'camille':'hugo']:[]});});
 if(entries[0])organizationWorkspace.assignments.push({id:'camille-first',personId:'camille',roleId:'legal-manager',scope:'company',scopeId:entries[0].id},{id:'alex-first',personId:'alex',roleId:'legal-reader',scope:'company',scopeId:entries[0].id});
 }
 organizationWorkspace.people.find(p=>p.id==='me').name=[account.firstname,account.lastname].filter(Boolean).join(' ')||'Votre compte';
 organizationWorkspace.people.find(p=>p.id==='me').email=account.email||'';
 // Existing company data is preserved; missing organisation links receive no paid licence.
 for(const entry of entries)if(!organizationWorkspace.links.some(l=>l.companyId===entry.id)){const cabinet=organizationWorkspace.cabinets.find(c=>c.id===organizationWorkspace.context.cabinetId)||organizationWorkspace.cabinets.find(c=>c.groupId===organizationWorkspace.context.groupId)||organizationWorkspace.cabinets[0];organizationWorkspace.links.push({companyId:entry.id,cabinetId:cabinet.id,plan:'unassigned',payer:'company',responsibles:[]});}
 try{localStorage.setItem(ORG_KEY,JSON.stringify(organizationWorkspace));}catch{}
}
function orgGroup(){return organizationWorkspace.groups.find(g=>g.id===organizationWorkspace.context.groupId);}
function orgCabinet(id){return organizationWorkspace.cabinets.find(c=>c.id===id);}
function orgLink(companyId){return organizationWorkspace.links.find(l=>l.companyId===companyId);}
function orgEntryGroup(companyId){return orgCabinet(orgLink(companyId)?.cabinetId)?.groupId;}
function orgScopeGroup(assignment){return assignment.scope==='group'?assignment.scopeId:assignment.scope==='cabinet'?orgCabinet(assignment.scopeId)?.groupId:orgEntryGroup(assignment.scopeId);}
function orgRole(id){return organizationWorkspace.roles.find(r=>r.id===id);}
function orgCanManage(personId='me',cabinetId=organizationWorkspace.context.cabinetId,groupId=organizationWorkspace.context.groupId){return organizationWorkspace.assignments.some(a=>a.personId===personId&&((a.scope==='group'&&a.scopeId===groupId&&orgRole(a.roleId)?.management==='group')||(cabinetId!=='all'&&a.scope==='cabinet'&&a.scopeId===cabinetId&&orgRole(a.roleId)?.management==='cabinet')));}
function orgCanManageCompany(id,personId='me'){const link=orgLink(id),cab=orgCabinet(link?.cabinetId);return !!cab&&orgCanManage(personId,cab.id,cab.groupId);}
function orgCompaniesInContext(){const {groupId,cabinetId}=organizationWorkspace.context;return companies.filter(e=>orgEntryGroup(e.id)===groupId&&(cabinetId==='all'||orgLink(e.id)?.cabinetId===cabinetId||organizationWorkspace.delegations.some(d=>d.companyId===e.id&&d.cabinetId===cabinetId)));}
function orgCompanyLegalLevel(personId,companyId,feature){
 const link=orgLink(companyId),cab=orgCabinet(link?.cabinetId);if(!cab)return{level:'none',sources:[]};
 const ranks={none:0,read:1,write:2};let level='none';const sources=[];
 for(const a of organizationWorkspace.assignments.filter(a=>a.personId===personId)){
  let applicable=a.scope==='group'&&a.scopeId===cab.groupId||a.scope==='company'&&a.scopeId===companyId||a.scope==='cabinet'&&a.scopeId===cab.id,cap=2;
  if(!applicable&&a.scope==='cabinet'){const delegated=organizationWorkspace.delegations.find(d=>d.companyId===companyId&&d.cabinetId===a.scopeId);if(delegated){applicable=true;cap=ranks[delegated.level];}}
  if(!applicable)continue;const role=orgRole(a.roleId),candidate=role?.permissions[feature]||'none',rank=Math.min(ranks[candidate],cap);if(rank){sources.push(role.name+' · '+orgScopeLabel(a));if(rank>ranks[level])level=rank===2?'write':'read';}
 }

 return{level,sources};
}
function orgLicenseLevel(plan,feature){if(['depot','annonces','procedures','utilisateurs','facturation','preferences'].includes(feature))return 'write';if(plan==='unassigned')return feature==='societe'?'write':'none';if(plan==='conservation')return feature==='certifications'?'none':'read';if(['documents','custom-decisions'].includes(feature)&&['acces','carnet'].includes(plan))return'read';return'write';}
function orgEffectiveAccess(personId,companyId,feature){const rights=orgCompanyLegalLevel(personId,companyId,feature),license=orgLicenseLevel(orgLink(companyId)?.plan||'unassigned',feature),rank={none:0,read:1,write:2},value=Math.min(rank[rights.level],rank[license]);return{...rights,roleLevel:rights.level,licenseLevel:license,level:value===2?'write':value===1?'read':'none'};}
function orgScopeLabel(a){if(a.scope==='group')return organizationWorkspace.groups.find(g=>g.id===a.scopeId)?.name||'Groupe inconnu';if(a.scope==='cabinet')return orgCabinet(a.scopeId)?.name||'Cabinet inconnu';return companies.find(c=>c.id===a.scopeId)?.data.name||'Société inconnue';}
function orgLevelLabel(level){return level==='write'?'Lecture et écriture':level==='read'?'Lecture seule':'Aucun accès';}
function orgContextSidebar(){const w=organizationWorkspace;return `<div class="org-sidebar-context"><label for="org-group-select">GROUPE</label><select id="org-group-select">${w.groups.map(g=>`<option value="${g.id}" ${w.context.groupId===g.id?'selected':''}>${escapeHTML(g.name)}</option>`).join('')}</select><label for="org-cabinet-select">CABINET · SOUS-GROUPE</label><select id="org-cabinet-select"><option value="all">Tous les cabinets</option>${w.cabinets.filter(c=>c.groupId===w.context.groupId).map(c=>`<option value="${c.id}" ${w.context.cabinetId===c.id?'selected':''}>${escapeHTML(c.name)}</option>`).join('')}</select></div>`;}
function syncOrganizationSidebar(){const owner=organizationWorkspace.people.find(p=>p.id==='me');if(owner){owner.name=fullName();owner.email=profile.email||'';}const box=$('#organization-context');if(box)box.innerHTML=orgContextSidebar();const link=$('[data-nav="organisation"]');if(link){link.classList.toggle('active',activeTab==='organisation');if(activeTab==='organisation')link.setAttribute('aria-current','page');else link.removeAttribute('aria-current');}}
function orgContextBanner(){const group=orgGroup(),cab=orgCabinet(organizationWorkspace.context.cabinetId);return `<div class="org-context-banner"><span>${icon('building')}<strong>${escapeHTML(group.name)}</strong><span>/</span>${escapeHTML(cab?.name||'Tous les cabinets')}</span><a href="organisation.html" class="text-link">Gérer l’organisation ${icon('arrow')}</a></div>`;}
function orgCompanyMetaHTML(entry){const link=orgLink(entry.id),cab=orgCabinet(link?.cabinetId),shared=organizationWorkspace.context.cabinetId!=='all'&&organizationWorkspace.context.cabinetId!==cab?.id;return `<div class="org-company-meta"><span>${escapeHTML(cab?.name||'Cabinet à définir')}${shared?' · Partagée':''}</span><span class="org-plan-tag">${escapeHTML(orgPlan(link?.plan).name)}</span></div><p class="org-responsibles">${link?.responsibles.length?'Responsable : '+escapeHTML(link.responsibles.map(id=>organizationWorkspace.people.find(p=>p.id===id)?.name||'').filter(Boolean).join(', ')):'Responsable à attribuer'}</p>`;}
function orgDashboardFilters(){return `<div class="org-dashboard-filters"><div><label for="org-dashboard-plan">Licence</label><select id="org-dashboard-plan"><option value="all">Toutes les licences</option>${ORG_PLANS.map(p=>`<option value="${p.id}" ${orgUI.plan===p.id?'selected':''}>${p.name}</option>`).join('')}</select></div><div><label for="org-dashboard-responsible">Responsable</label><select id="org-dashboard-responsible"><option value="all">Tous les responsables</option><option value="none" ${orgUI.responsible==='none'?'selected':''}>Non attribué</option>${orgGroupPeople().map(p=>`<option value="${p.id}" ${orgUI.responsible===p.id?'selected':''}>${escapeHTML(p.name)}</option>`).join('')}</select></div></div>`;}
function orgCommit(change,message){const before=JSON.stringify(organizationWorkspace);try{change();}catch(error){organizationWorkspace=JSON.parse(before);throw error;}try{localStorage.setItem(ORG_KEY,JSON.stringify(organizationWorkspace));return true;}catch{organizationWorkspace=JSON.parse(before);throw new Error('Le stockage local est indisponible. Vos modifications ne sont pas enregistrées ; vous pouvez réessayer.');}}
function orgResetFilters(){orgUI.query='';orgUI.plan='all';orgUI.responsible='all';orgUI.page=1;orgUI.selected.clear();companyPage=1;companyQuery='';}
function changeOrgContext(groupId,cabinetId='all'){
 try{orgCommit(()=>{const group=organizationWorkspace.groups.find(g=>g.id===groupId);if(!group)throw new Error('Groupe introuvable.');if(cabinetId!=='all'&&!organizationWorkspace.cabinets.some(c=>c.id===cabinetId&&c.groupId===groupId))throw new Error('Ce cabinet ne fait pas partie de ce groupe.');organizationWorkspace.context={groupId,cabinetId};});orgResetFilters();const personal=['espace','organisation','compte','notifications'].includes(activeTab);if(personal)render();else location.href='dashboard.html#espace';}catch(error){toast(error.message);syncOrganizationSidebar();}
}
function orgAlignCompanyContext(id){const link=orgLink(id),cab=orgCabinet(link?.cabinetId);if(!cab||orgCompaniesInContext().some(e=>e.id===id))return;organizationWorkspace.context={groupId:cab.groupId,cabinetId:cab.id};try{localStorage.setItem(ORG_KEY,JSON.stringify(organizationWorkspace));}catch{}orgResetFilters();}
function orgTabHref(tab){return '#organisation/'+tab;}
function organizationPage(){const requested=location.hash.split('/')[1];orgUI.tab=['portfolio','cabinets','people','roles','licenses'].includes(requested)?requested:'portfolio';const tabs=[['portfolio','Portefeuille'],['cabinets','Cabinets'],['people','Équipes & périmètres'],['roles','Rôles & accès'],['licenses','Licences & facturation']],entries=orgCompaniesInContext(),group=orgGroup();return `<div class="org-page">${orgContextBanner()}<div class="org-page-intro"><div><span class="org-eyebrow">GROUPE → CABINET → SOCIÉTÉ</span><h2>Un portefeuille.<br>Des cabinets bien organisés.</h2><p>Chaque société garde sa licence. Chaque personne intervient dans son périmètre.</p></div><button class="button" data-org-action="group-new">${icon('plus')}Nouveau groupe</button></div><div class="org-stats"><article><span>Cabinets du groupe</span><strong>${organizationWorkspace.cabinets.filter(c=>c.groupId===group.id).length}</strong></article><article><span>Sociétés du périmètre</span><strong>${entries.length}</strong></article><article><span>Licences attribuées</span><strong>${entries.filter(e=>orgLink(e.id)?.plan!=='unassigned').length}</strong></article><article><span>Personnes habilitées</span><strong>${new Set(orgAssignmentsInContext().map(a=>a.personId)).size}</strong></article></div><nav class="org-tabs" aria-label="Administration de l’organisation">${tabs.map(([id,label])=>`<a href="${orgTabHref(id)}" ${orgUI.tab===id?'aria-current="page"':''}>${label}</a>`).join('')}</nav><div id="org-content">${orgUI.tab==='cabinets'?orgCabinetsPanel():orgUI.tab==='people'?orgPeoplePanel():orgUI.tab==='roles'?orgRolesPanel():orgUI.tab==='licenses'?orgLicensesPanel():orgPortfolioPanel()}</div><p class="org-demo-note">Organisation de démonstration, enregistrée dans ce navigateur. Aucun abonnement n’est souscrit, aucun paiement ni invitation n’est envoyé. Les permissions présentées devront être vérifiées côté serveur dans l’application réelle.</p></div>`;}
function orgFilteredCompanies(){const query=normalizedSearch(orgUI.query);return orgCompaniesInContext().filter(e=>normalizedSearch(e.data.name+' '+e.data.siren+' '+orgCabinet(orgLink(e.id)?.cabinetId)?.name).includes(query)&&(orgUI.plan==='all'||orgLink(e.id)?.plan===orgUI.plan)&&(orgUI.responsible==='all'||orgUI.responsible==='none'&&!orgLink(e.id)?.responsibles.length||orgLink(e.id)?.responsibles.includes(orgUI.responsible))).sort((a,b)=>a.data.name.localeCompare(b.data.name,'fr'));}
function orgPortfolioPanel(){return `<section class="panel org-panel"><div class="org-panel-head"><div><h3>Les sociétés du portefeuille</h3><p>Rattachement principal, licence et responsables. Un partage ne duplique pas le dossier.</p></div><button class="button button-primary" data-action="add-company">${icon('plus')}Ajouter une société</button></div><div class="org-filters"><div class="form-field"><label for="org-query">Rechercher une société</label><input id="org-query" type="search" value="${escapeHTML(orgUI.query)}" placeholder="Nom, SIREN, cabinet…"></div>${orgDashboardFilters()}</div><div id="org-bulk">${orgBulkHTML()}</div><div class="org-table-scroll" tabindex="0" role="region" aria-label="Portefeuille des sociétés"><table class="org-table"><thead><tr><th><span class="sr-only">Sélection</span></th><th>Société</th><th>Cabinet principal</th><th>Licence</th><th>Responsable(s)</th><th>Actions</th></tr></thead><tbody id="org-company-rows">${orgPortfolioRows()}</tbody></table></div><div id="org-portfolio-pagination">${orgPortfolioPagination()}</div></section>`;}
function orgBulkHTML(){return `<div class="org-bulk-bar"><span>${orgUI.selected.size} société(s) sélectionnée(s)</span><button class="text-link" data-org-action="select-page">Sélectionner la page</button>${orgUI.selected.size?'<button class="text-link" data-org-action="clear-selection">Effacer</button>':''}<button class="button" data-org-action="bulk-license" ${!orgUI.selected.size?'disabled':''}>Modifier les licences</button></div>`;}
function orgPortfolioRows(){const all=orgFilteredCompanies();orgUI.page=RGCollections.clamp(orgUI.page,all.length,10);return all.slice((orgUI.page-1)*10,orgUI.page*10).map(e=>{const l=orgLink(e.id),cab=orgCabinet(l.cabinetId),shared=organizationWorkspace.context.cabinetId!=='all'&&cab.id!==organizationWorkspace.context.cabinetId;return `<tr><td><input type="checkbox" data-org-select="${e.id}" aria-label="Sélectionner ${escapeHTML(e.data.name)}" ${orgUI.selected.has(e.id)?'checked':''} ${!orgCanManageCompany(e.id)?'disabled':''}></td><td><a href="societe.html?societe=${e.id}"><strong>${escapeHTML(e.data.name)}</strong></a><small>SIREN ${escapeHTML(e.data.siren)}</small><span class="org-mobile-company-meta">${escapeHTML(cab.name)} · ${orgPlan(l.plan).name}</span>${shared?'<span class="org-share-badge">Accès partagé</span>':''}</td><td>${escapeHTML(cab.name)}</td><td><span class="org-plan-tag">${orgPlan(l.plan).name}</span></td><td>${escapeHTML(l.responsibles.map(id=>organizationWorkspace.people.find(p=>p.id===id)?.name||'').filter(Boolean).join(', ')||'À attribuer')}</td><td><div class="org-row-actions"><button class="text-link" data-org-action="company-settings" data-id="${e.id}" ${!orgCanManageCompany(e.id)?'disabled':''}>Gérer</button><button class="text-link" data-org-action="company-share" data-id="${e.id}" ${!orgCanManageCompany(e.id)?'disabled':''}>Partager</button></div></td></tr>`;}).join('')||'<tr><td colspan="6" class="org-empty">Aucune société dans ce périmètre ou pour ces filtres.</td></tr>';}
function orgPortfolioPagination(){return RGCollections.render({id:'org-portfolio',total:orgFilteredCompanies().length,page:orgUI.page,pageSize:10,sizes:[10],label:'sociétés',controls:'org-company-rows'});}
function refreshOrgPortfolio(){if(!$('#org-company-rows'))return;$('#org-company-rows').innerHTML=orgPortfolioRows();$('#org-bulk').innerHTML=orgBulkHTML();$('#org-portfolio-pagination').innerHTML=orgPortfolioPagination();}
function orgCabinetsPanel(){const group=orgGroup();return `<section><div class="org-panel-head"><div><h3>Les cabinets de ${escapeHTML(group.name)}</h3><p>Un sous-groupe par cabinet, avec ses administrateurs et ses sociétés.</p></div><button class="button button-primary" data-org-action="cabinet-new" ${!orgCanManage('me','all')?'disabled':''}>${icon('plus')}Nouveau cabinet</button></div><div class="org-cabinet-grid">${organizationWorkspace.cabinets.filter(c=>c.groupId===group.id).map(c=>{const ids=organizationWorkspace.links.filter(l=>l.cabinetId===c.id&&companies.some(e=>e.id===l.companyId)),admins=organizationWorkspace.assignments.filter(a=>a.scope==='cabinet'&&a.scopeId===c.id&&orgRole(a.roleId)?.management==='cabinet');return `<article class="panel org-cabinet-card"><span class="org-cabinet-monogram">${icon('building')}</span><h3>${escapeHTML(c.name)}</h3><p>${escapeHTML(c.city||'Ville non renseignée')}</p><div><strong>${ids.length}</strong> société(s) rattachée(s)</div><p class="org-small">Administrateur(s) : ${escapeHTML(admins.map(a=>organizationWorkspace.people.find(p=>p.id===a.personId)?.name).join(', ')||'À attribuer')}</p><div class="org-row-actions"><button class="text-link" data-org-action="cabinet-open" data-id="${c.id}">Voir le portefeuille ${icon('arrow')}</button><button class="text-link" data-org-action="cabinet-edit" data-id="${c.id}" ${!orgCanManage('me',c.id)?'disabled':''}>Modifier</button></div></article>`;}).join('')}</div></section>`;}
function orgGroupPeople(){const ids=new Set(organizationWorkspace.assignments.filter(a=>orgScopeGroup(a)===orgGroup().id).map(a=>a.personId));for(const link of organizationWorkspace.links.filter(l=>orgEntryGroup(l.companyId)===orgGroup().id))for(const id of link.responsibles)ids.add(id);return organizationWorkspace.people.filter(p=>ids.has(p.id));}
function orgPeoplePanel(){return `<section class="panel org-panel"><div class="org-panel-head"><div><h3>Équipes et périmètres</h3><p>Plusieurs attributions peuvent coexister pour une personne. L’administration ne donne pas automatiquement accès aux dossiers juridiques.</p></div><button class="button button-primary" data-org-action="assignment-new">${icon('plus')}Ajouter une attribution</button></div><div class="org-filters"><div class="form-field"><label for="org-person-query">Rechercher une personne</label><input id="org-person-query" type="search" value="${escapeHTML(orgUI.peopleQuery)}" placeholder="Nom, adresse e-mail…"></div></div><div class="org-table-scroll"><table class="org-table"><thead><tr><th>Personne</th><th>Rôle</th><th>Périmètre</th><th>Nature</th><th>Action</th></tr></thead><tbody id="org-assignment-rows">${orgAssignmentRows()}</tbody></table></div><div id="org-people-pagination">${orgPeoplePagination()}</div></section>`;}
function orgAssignmentsInContext(){const cabinetId=organizationWorkspace.context.cabinetId,ids=new Set(orgCompaniesInContext().map(e=>e.id));return organizationWorkspace.assignments.filter(a=>orgScopeGroup(a)===orgGroup().id&&(cabinetId==='all'||a.scope==='group'||a.scope==='cabinet'&&a.scopeId===cabinetId||a.scope==='company'&&ids.has(a.scopeId)));}
function orgFilteredAssignments(){return orgAssignmentsInContext().filter(a=>normalizedSearch((organizationWorkspace.people.find(p=>p.id===a.personId)?.name||'')+' '+(organizationWorkspace.people.find(p=>p.id===a.personId)?.email||'')).includes(normalizedSearch(orgUI.peopleQuery)));}
function orgAssignmentRows(){const all=orgFilteredAssignments();orgUI.peoplePage=RGCollections.clamp(orgUI.peoplePage,all.length,10);return all.slice((orgUI.peoplePage-1)*10,orgUI.peoplePage*10).map(a=>{const p=organizationWorkspace.people.find(p=>p.id===a.personId),r=orgRole(a.roleId);return `<tr><td><strong>${escapeHTML(p.name)}</strong><small>${escapeHTML(p.email||'E-mail non renseigné')}</small></td><td>${escapeHTML(r.name)}</td><td><span class="org-scope-badge">${a.scope==='group'?'Groupe':a.scope==='cabinet'?'Cabinet':'Société'}</span><small>${escapeHTML(orgScopeLabel(a))}</small></td><td>${r.management==='none'?'Accès aux fonctionnalités':'Administration de structure'}</td><td>${a.protected?'<span class="org-small">Propriétaire protégé</span>':`<button class="text-link danger-text" data-org-action="assignment-remove" data-id="${a.id}">Retirer</button>`}</td></tr>`;}).join('')||'<tr><td colspan="5" class="org-empty">Aucune attribution ne correspond à cette recherche.</td></tr>';}
function orgPeoplePagination(){return RGCollections.render({id:'org-people',total:orgFilteredAssignments().length,page:orgUI.peoplePage,pageSize:10,sizes:[10],label:'attributions',controls:'org-assignment-rows'});}
function orgRolesPanel(){return `<section><div class="org-panel-head"><div><h3>Rôles réutilisables</h3><p>Une grille de fonctionnalités, indépendante du périmètre d’attribution et de la licence.</p></div><button class="button button-primary" data-org-action="role-new">${icon('plus')}Créer un rôle</button></div><div class="org-role-grid">${organizationWorkspace.roles.filter(r=>!r.groupId||r.groupId===orgGroup().id).map(r=>`<article class="panel org-role-card"><span class="badge">${r.management==='group'?'Administration groupe':r.management==='cabinet'?'Administration cabinet':'Fonctionnalités'}</span><h3>${escapeHTML(r.name)}</h3><p>${r.management==='none'?Object.values(r.permissions).filter(l=>l!=='none').length+' fonctionnalités autorisées':'Aucun accès juridique implicite'}</p><button class="text-link" data-org-action="role-view" data-id="${r.id}">${r.protected?'Voir la grille':'Modifier la grille'} ${icon('arrow')}</button></article>`).join('')}</div><section class="panel org-inspector"><h3>Vérifier un accès</h3><p>Le résultat combine le périmètre, les permissions du rôle et les fonctionnalités de la licence.</p><div class="form-row"><div class="form-field"><label for="org-inspector-person">Personne à vérifier</label><select id="org-inspector-person">${orgGroupPeople().map(p=>`<option value="${p.id}" ${orgUI.inspectorPerson===p.id?'selected':''}>${escapeHTML(p.name)}</option>`).join('')}</select></div><div class="form-field"><label for="org-inspector-company">Société concernée</label><select id="org-inspector-company">${orgCompaniesInContext().map(e=>`<option value="${e.id}" ${orgUI.inspectorCompany===e.id?'selected':''}>${escapeHTML(e.data.name)}</option>`).join('')}</select></div></div><div class="form-field"><label for="org-inspector-feature">Fonctionnalité à vérifier</label><select id="org-inspector-feature">${ORG_FEATURES.map(([id,name])=>`<option value="${id}" ${orgUI.inspectorFeature===id?'selected':''}>${name}</option>`).join('')}</select></div><div id="org-inspector-result" role="status">${orgInspectorHTML()}</div></section></section>`;}
function orgInspectorHTML(){const entry=orgCompaniesInContext().find(e=>e.id===orgUI.inspectorCompany)||orgCompaniesInContext()[0];if(!entry)return '<p>Aucune société dans ce périmètre.</p>';orgUI.inspectorCompany=entry.id;const result=orgEffectiveAccess(orgUI.inspectorPerson,entry.id,orgUI.inspectorFeature);return `<div class="org-access-result"><div><span>Permission du rôle</span><strong>${orgLevelLabel(result.roleLevel)}</strong></div><span>∩</span><div><span>Licence ${orgPlan(orgLink(entry.id)?.plan).name}</span><strong>${orgLevelLabel(result.licenseLevel)}</strong></div><span>=</span><div><span>Accès effectif</span><strong>${orgLevelLabel(result.level)}</strong></div></div><p class="org-small">${result.sources.length?escapeHTML(result.sources.join(' · ')):'Aucune attribution couvrant cette société et cette fonctionnalité.'}</p><p class="org-small">Dépôt et annonces légales : services distincts de la licence des registres, soumis aux permissions attribuées.</p>`;}
function orgLicensesPanel(){const entries=orgCompaniesInContext(),payerLabel=id=>id==='group'?'Groupe':id==='cabinet'?'Cabinet':'Société',known=entries.reduce((sum,e)=>sum+(orgPlan(orgLink(e.id).plan).price||0),0),unknown=entries.filter(e=>orgPlan(orgLink(e.id).plan).price===null).length;return `<section><div class="org-panel-head"><div><h3>Une licence par société</h3><p>La facturation peut être centralisée sans uniformiser les licences du portefeuille.</p></div><a class="button" href="#organisation/portfolio">Gérer les licences</a></div><div class="org-license-summary"><div><span>Tarifs annuels connus</span><strong>${money(known*100)}</strong><small>${unknown} société(s) sans tarif renseigné · fiscalité à confirmer</small></div><p>Comparaison indicative des tarifs fournis. Les licences de démonstration, les plafonds de certifications et les payeurs ne représentent aucun contrat ni facture réelle.</p></div><div class="org-table-scroll panel"><table class="org-table"><thead><tr><th>Licence</th><th>Sociétés</th><th>Tarif annuel / société</th><th>Certifications incluses</th></tr></thead><tbody>${ORG_PLANS.map(p=>`<tr><td>${p.name}</td><td>${entries.filter(e=>orgLink(e.id).plan===p.id).length}</td><td>${p.price===null?'À confirmer':money(p.price*100)+(p.id==='conservation'?' HT':'')}</td><td>${p.certifications===null?'—':p.certifications}</td></tr>`).join('')}</tbody></table></div><section class="panel org-payers"><h3>Répartition des payeurs</h3>${['group','cabinet','company'].map(p=>`<div><span>${payerLabel(p)}</span><strong>${entries.filter(e=>orgLink(e.id).payer===p).length} société(s)</strong></div>`).join('')}<p class="org-small">Le payeur se règle dans la fiche de rattachement de chaque société. Les formalités et achats ponctuels sont hors de cette comparaison.</p></section></section>`;}
function orgFormActions(label='Enregistrer'){return `<p id="org-form-status" role="status" class="register-form-status"></p><div class="modal-actions"><button class="button" type="button" data-action="close-modal">Annuler</button><button type="submit" class="button button-primary">${label}</button></div>`;}
function orgModal(title,body){modal(title,body);$('#modal').classList.add('org-wide');}
function orgCabinetOptions(selected,all=false){return (all?'<option value="all">Tous les cabinets</option>':'')+organizationWorkspace.cabinets.filter(c=>c.groupId===orgGroup().id).map(c=>`<option value="${c.id}" ${selected===c.id?'selected':''}>${escapeHTML(c.name)}</option>`).join('');}
function orgPlanOptions(selected){return ORG_PLANS.map(p=>`<option value="${p.id}" ${p.id===selected?'selected':''}>${p.name}</option>`).join('');}
function orgOpenGroupForm(){orgModal('Créer un groupe',`<p class="modal-description">Un nouvel espace d’organisation avec son premier cabinet. Votre compte en devient administrateur ; un rôle juridique distinct est attribué pour préparer les dossiers.</p><form id="org-group-form">${field('groupName','Nom du groupe','','text','maxlength="100"')}${field('cabinetName','Nom du premier cabinet','','text','maxlength="100"')}<p class="demo-note">Création locale de démonstration, sans contrat ni nouvelle société juridique.</p>${orgFormActions('Créer le groupe')}</form>`);}
function orgOpenCabinetForm(id=''){const row=orgCabinet(id);if(!orgCanManage('me',row?.id||'all'))return toast('Vous ne pouvez pas administrer ce périmètre.');orgModal(row?'Modifier le cabinet':'Nouveau cabinet',`<p class="modal-description">Sous-groupe de ${escapeHTML(orgGroup().name)}.</p><form id="org-cabinet-form" data-id="${id}">${field('cabinetName','Nom du cabinet',row?.name||'','text','maxlength="100"')}<div class="form-field"><label for="org-cabinet-city">Ville · facultatif</label><input id="org-cabinet-city" name="city" maxlength="120" value="${escapeHTML(row?.city||'')}"></div>${orgFormActions(row?'Enregistrer le cabinet':'Créer le cabinet')}</form>`);}
function orgOpenCompanySettings(id){const entry=companies.find(e=>e.id===id),link=orgLink(id);if(!entry||!link||!orgCanManageCompany(id))return toast('Ce rattachement est géré par son cabinet principal.');orgModal('Rattachement et licence',`<p class="modal-description">${escapeHTML(entry.data.name)} · SIREN ${escapeHTML(entry.data.siren)}</p><form id="org-company-form" data-id="${id}" data-base="${escapeHTML(JSON.stringify(link))}"><div class="form-row"><div class="form-field"><label for="org-settings-cabinet">Cabinet principal</label><select id="org-settings-cabinet" name="cabinetId" required>${orgCabinetOptions(link.cabinetId)}</select></div><div class="form-field"><label for="org-settings-plan">Licence de cette société</label><select id="org-settings-plan" name="plan">${orgPlanOptions(link.plan)}</select></div></div><div class="form-field"><label for="org-settings-payer">Payeur</label><select id="org-settings-payer" name="payer">${[['group','Groupe'],['cabinet','Cabinet'],['company','Société']].map(([id,label])=>`<option value="${id}" ${link.payer===id?'selected':''}>${label}</option>`).join('')}</select></div><fieldset class="org-check-list"><legend>Responsables du dossier · facultatif</legend>${orgGroupPeople().map(p=>`<label><input type="checkbox" name="responsible" value="${p.id}" ${link.responsibles.includes(p.id)?'checked':''}>${escapeHTML(p.name)}</label>`).join('')}</fieldset><p class="demo-note">Un transfert conserve le dossier, ses registres et son historique. Les attributions au cabinet précédent ne suivent pas automatiquement ; les accès spécifiques à la société sont conservés. Être responsable ne donne aucun droit supplémentaire.</p>${orgFormActions('Vérifier les modifications')}</form>`);}
let orgPendingChange=null;
function orgReviewCompany(form){const values=new FormData(form),id=form.dataset.id,link=orgLink(id),cab=orgCabinet(String(values.get('cabinetId'))),entry=companies.find(e=>e.id===id);if(!orgCanManageCompany(id)||!cab||cab.groupId!==orgEntryGroup(id))throw new Error('Le cabinet doit appartenir au même groupe.');const next={...link,cabinetId:cab.id,plan:orgPlan(values.get('plan')).id,payer:String(values.get('payer')),responsibles:values.getAll('responsible').filter(id=>organizationWorkspace.people.some(p=>p.id===id))};orgPendingChange={kind:'company',id,base:form.dataset.base,next};orgModal('Vérifier le rattachement',`<p class="modal-description">${escapeHTML(entry.data.name)}</p><dl class="org-review-list"><div><dt>Cabinet principal</dt><dd>${escapeHTML(orgCabinet(link.cabinetId).name)} → ${escapeHTML(cab.name)}</dd></div><div><dt>Licence</dt><dd>${orgPlan(link.plan).name} → ${orgPlan(next.plan).name}</dd></div><div><dt>Payeur</dt><dd>${next.payer==='group'?'Groupe':next.payer==='cabinet'?'Cabinet':'Société'}</dd></div><div><dt>Responsables</dt><dd>${escapeHTML(next.responsibles.map(id=>organizationWorkspace.people.find(p=>p.id===id).name).join(', ')||'Aucun')}</dd></div></dl><p class="demo-note">Les registres et l’historique restent attachés à la même société. Cette confirmation ne souscrit aucun abonnement et ne déclenche aucun paiement.</p><form id="org-confirm-form">${orgFormActions('Confirmer les modifications')}</form>`);}
function orgOpenShare(id){const entry=companies.find(e=>e.id===id),link=orgLink(id);if(!entry||!orgCanManageCompany(id))return toast('Le partage est réservé au cabinet principal ou à l’administrateur du groupe.');orgModal('Partager le dossier avec un cabinet',`<p class="modal-description">${escapeHTML(entry.data.name)} reste rattachée à ${escapeHTML(orgCabinet(link.cabinetId).name)}. Les cabinets choisis accèdent au même dossier.</p><form id="org-share-form" data-id="${id}"><fieldset class="org-share-cabinets"><legend>Cabinets du même groupe</legend>${organizationWorkspace.cabinets.filter(c=>c.groupId===orgEntryGroup(id)&&c.id!==link.cabinetId).map(c=>{const d=organizationWorkspace.delegations.find(d=>d.companyId===id&&d.cabinetId===c.id);return `<div><label><input type="checkbox" name="cabinet" value="${c.id}" ${d?'checked':''}>${escapeHTML(c.name)}</label><label class="sr-only" for="share-${c.id}">Plafond du partage pour ${escapeHTML(c.name)}</label><select id="share-${c.id}" name="level-${c.id}"><option value="read" ${d?.level!=='write'?'selected':''}>Lecture seule</option><option value="write" ${d?.level==='write'?'selected':''}>Lecture et écriture</option></select></div>`;}).join('')||'<p>Aucun autre cabinet dans ce groupe.</p>'}</fieldset><p class="demo-note">Le partage plafonne les permissions juridiques déjà attribuées aux membres du cabinet destinataire. Il n’accorde aucun rôle juridique à ses administrateurs par défaut et ne modifie ni la licence ni le payeur.</p>${orgFormActions('Enregistrer le partage')}</form>`);}
function orgOpenBulkLicense(){const ids=[...orgUI.selected].filter(id=>orgCompaniesInContext().some(e=>e.id===id)&&orgCanManageCompany(id));if(!ids.length)return;orgModal('Modifier plusieurs licences',`<p class="modal-description">${ids.length} société(s). Les cabinets, responsables et payeurs restent ceux de chaque dossier.</p><form id="org-bulk-license-form" data-ids="${ids.join(',')}"><div class="form-field"><label for="org-bulk-plan">Nouvelle licence</label><select name="plan" id="org-bulk-plan">${orgPlanOptions('premium')}</select></div><div class="org-selected-companies">${ids.map(id=>`<p><strong>${escapeHTML(companies.find(e=>e.id===id).data.name)}</strong><span>${orgPlan(orgLink(id).plan).name}</span></p>`).join('')}</div>${orgFormActions('Vérifier le changement de licences')}</form>`);}
function orgReviewBulk(form){const ids=form.dataset.ids.split(',').filter(id=>orgCompaniesInContext().some(e=>e.id===id)&&orgCanManageCompany(id)),plan=orgPlan(new FormData(form).get('plan'));if(!ids.length)throw new Error('Aucune société administrable sélectionnée.');orgPendingChange={kind:'licenses',ids,plan:plan.id,bases:ids.map(id=>[id,JSON.stringify(orgLink(id))])};orgModal('Confirmer les licences',`<p class="modal-description">Nouvelle licence : ${plan.name} · ${ids.length} société(s)</p><div class="org-selected-companies">${ids.map(id=>`<p><strong>${escapeHTML(companies.find(e=>e.id===id).data.name)}</strong><span>${orgPlan(orgLink(id).plan).name} → ${plan.name}</span></p>`).join('')}</div><p class="demo-note">Aucun achat ni paiement réel. Seules les licences des sociétés listées seront modifiées dans cette maquette.</p><form id="org-confirm-form">${orgFormActions('Confirmer les modifications')}</form>`);}
function orgOpenAssignment(){orgModal('Attribuer un rôle et un périmètre',`<p class="modal-description">Une attribution porte sur le groupe, un cabinet ou une société. Ajoutez plusieurs attributions pour cumuler des périmètres différents.</p><form id="org-assignment-form"><div class="form-field"><label for="org-assignment-person">Personne</label><select id="org-assignment-person" name="personId"><option value="new">Ajouter une personne</option>${orgGroupPeople().map(p=>`<option value="${p.id}">${escapeHTML(p.name)} · ${escapeHTML(p.email)}</option>`).join('')}</select></div><fieldset data-org-new-person>${field('personName','Nom et prénom','','text','maxlength="120"')}${field('personEmail','Adresse e-mail','','email','maxlength="150"')}</fieldset><div class="form-field"><label for="org-assignment-role">Rôle</label><select id="org-assignment-role" name="roleId">${organizationWorkspace.roles.filter(r=>!r.groupId||r.groupId===orgGroup().id).map(r=>`<option value="${r.id}">${escapeHTML(r.name)}</option>`).join('')}</select></div><div class="form-row"><div class="form-field"><label for="org-assignment-scope">Type de périmètre</label><select id="org-assignment-scope" name="scope"><option value="group">Groupe</option><option value="cabinet">Cabinet</option><option value="company">Société</option></select></div><div class="form-field"><label for="org-assignment-target">Périmètre concerné</label><select id="org-assignment-target" name="scopeId"></select></div></div><p class="demo-note">L’administration de structure et les droits juridiques sont indépendants. Aucun e-mail ni invitation n’est envoyé par cette attribution locale.</p>${orgFormActions('Enregistrer l’attribution')}</form>`);orgRefreshAssignmentTargets();}
function orgRefreshAssignmentTargets(){const form=$('#org-assignment-form');if(!form)return;const role=orgRole(form.elements.roleId.value),scope=form.elements.scope;if(role.management==='group')scope.value='group';if(role.management==='cabinet')scope.value='cabinet';scope.disabled=role.management!=='none';const options=scope.value==='group'?[{id:orgGroup().id,name:orgGroup().name}]:scope.value==='cabinet'?organizationWorkspace.cabinets.filter(c=>c.groupId===orgGroup().id):orgCompaniesInContext().map(c=>({id:c.id,name:c.data.name}));form.elements.scopeId.innerHTML=options.map(r=>`<option value="${r.id}">${escapeHTML(r.name)}</option>`).join('');}
function orgOpenRole(id=''){const role=orgRole(id),protectedRole=role?.protected;if(role?.groupId&&role.groupId!==orgGroup().id)return toast('Ce rôle appartient à un autre groupe.');orgModal(protectedRole?'Grille du rôle':'Définir un rôle juridique',`<p class="modal-description">${protectedRole?'Rôle de référence protégé.':'Le rôle pourra être attribué à un groupe, un cabinet ou une société. Les licences restent indépendantes.'}</p><form id="org-role-form" data-id="${id}">${field('roleName','Nom du rôle',role?.name||'','text',`maxlength="80" ${protectedRole?'readonly':''}`)}<div class="org-permission-grid"><div class="org-permission-head"><strong>Fonctionnalité</strong><span>Niveau autorisé</span></div>${ORG_FEATURES.map(([key,label])=>`<div><label for="org-perm-${key}">${label}</label><select id="org-perm-${key}" name="permission-${key}" ${protectedRole?'disabled':''}>${[['none','Aucun accès'],['read','Lecture seule'],['write','Lecture et écriture']].map(([id,label])=>`<option value="${id}" ${(role?.permissions[key]||'none')===id?'selected':''}>${label}</option>`).join('')}</select></div>`).join('')}</div>${protectedRole?'<p class="demo-note">'+(role.management!=='none'?'Ce rôle administre la structure, sans autoriser la lecture des dossiers juridiques.':'Le périmètre et la licence de la société limitent cette grille.')+'</p><button class="button" type="button" data-action="close-modal">Fermer</button>':orgFormActions('Enregistrer le rôle')}</form>`);}
function orgCompanyLicenseCard(){const link=orgLink(currentCompany.id),plan=orgPlan(link?.plan),cab=orgCabinet(link?.cabinetId);return `<section class="company-subscription subscription-card-v2"><div class="subscription-pass-head"><div><span>LICENCE DE ${escapeHTML(company.name)}</span><h3>${plan.name}<i>.</i></h3><small>Licence propre à cette société · Démonstration</small></div><span class="subscription-pass-mark">RG</span></div><div class="subscription-pass-body"><p class="org-small">${escapeHTML(cab?.name||'Cabinet à définir')} · ${escapeHTML(organizationWorkspace.groups.find(g=>g.id===cab?.groupId)?.name||'')}</p><div class="subscription-balance-row"><span>Certifications prévues par l’offre</span><strong>${plan.certifications===null?'—':plan.certifications}</strong></div><p class="org-small">Consommation et solde non raccordés. ${plan.price!==null?'Tarif annuel fourni : '+money(plan.price*100)+(plan.id==='conservation'?' HT':'')+'.':'Tarif à confirmer.'}</p><button class="button subscription-cert-button" data-org-action="company-settings" data-id="${currentCompany.id}">Gérer cette licence ${icon('arrow')}</button></div><div class="subscription-pass-footer"><a href="organisation.html#organisation/licenses">${icon('building')}<span>Licences du portefeuille</span>${icon('arrow')}</a><a href="offres.html">${icon('spark')}<span>Comparer les offres</span>${icon('arrow')}</a></div></section>`;}
function orgAddCompanyFields(){const cab=organizationWorkspace.context.cabinetId;return `<div class="form-row"><div class="form-field"><label for="org-add-cabinet">Cabinet de rattachement</label><select id="org-add-cabinet" name="orgCabinet" required>${orgCabinetOptions(cab)}</select></div><div class="form-field"><label for="org-add-plan">Licence initiale</label><select id="org-add-plan" name="orgPlan">${orgPlanOptions('unassigned')}</select></div></div>`;}
function saveCompanyWithOrganization(form){const values=new FormData(form),entry=companyData({...blankCompany,name:String(values.get('name')),siren:String(values.get('siren')),form:String(values.get('form')||'').trim()||'À renseigner',city:String(values.get('city')||'').trim()||'À renseigner'}),status=$('#add-company-status');if(!entry){status.textContent='Renseignez un nom et un SIREN de 9 chiffres.';return;}const id=companyId(entry),cab=orgCabinet(String(values.get('orgCabinet')));if(companies.some(c=>c.id===id)){status.textContent='Cette société existe déjà. Utilisez son rattachement ou le partage du dossier.';return;}if(!cab||cab.groupId!==orgGroup().id||!orgCanManage('me',cab.id)){status.textContent='Choisissez un cabinet que vous administrez.';return;}if(companies.length>=1000){status.textContent='1 000 sociétés maximum dans la démonstration.';return;}const before=localStorage.getItem('rg-demo-companies'),beforeOrg=JSON.stringify(organizationWorkspace);try{companies.push({id,data:entry,example:false,settings:{reminders:true,digest:false}});organizationWorkspace.links.push({companyId:id,cabinetId:cab.id,plan:orgPlan(values.get('orgPlan')).id,payer:'group',responsibles:[]});localStorage.setItem('rg-demo-companies',JSON.stringify(companies));localStorage.setItem(ORG_KEY,JSON.stringify(organizationWorkspace));}catch{companies=companies.filter(e=>e.id!==id);organizationWorkspace=JSON.parse(beforeOrg);try{if(before===null)localStorage.removeItem('rg-demo-companies');else localStorage.setItem('rg-demo-companies',before);}catch{}status.textContent='L’ajout n’a pas pu être enregistré. Vos saisies sont conservées.';return;}orgResetFilters();$('#modal').close();render();toast('La société a été ajoutée au portefeuille du cabinet.');}
function orgCompaniesPicker(){orgUI.pickerPage=1;orgUI.pickerQuery='';orgModal('Choisir une société',`<p class="modal-description">${escapeHTML(orgGroup().name)} · ${escapeHTML(orgCabinet(organizationWorkspace.context.cabinetId)?.name||'Tous les cabinets')}</p><div class="form-field"><label for="org-picker-query">Rechercher dans ce périmètre</label><input id="org-picker-query" type="search" placeholder="Nom ou SIREN…"></div><div id="org-picker-results"></div><button class="button company-picker-add" data-action="add-company">${icon('plus')}Ajouter une société</button>`);refreshOrgPicker();}
function refreshOrgPicker(){const all=orgCompaniesInContext().filter(e=>normalizedSearch(e.data.name+' '+e.data.siren).includes(normalizedSearch(orgUI.pickerQuery)));orgUI.pickerPage=RGCollections.clamp(orgUI.pickerPage,all.length,8);$('#org-picker-results').innerHTML=`<div class="company-picker-list">${all.slice((orgUI.pickerPage-1)*8,orgUI.pickerPage*8).map(e=>`<button class="modal-option" data-company-open="${e.id}"><span class="workspace-avatar">${escapeHTML(e.data.name.charAt(0))}</span><span><strong>${escapeHTML(e.data.name)}</strong><small>${escapeHTML(orgCabinet(orgLink(e.id)?.cabinetId)?.name||'')} · ${orgPlan(orgLink(e.id)?.plan).name}</small></span>${icon('arrow')}</button>`).join('')||'<p>Aucune société dans ce périmètre.</p>'}</div>${RGCollections.render({id:'org-picker',total:all.length,page:orgUI.pickerPage,pageSize:8,sizes:[8],label:'sociétés',controls:'org-picker-results'})}`;}
function orgSaveForm(form){const values=new FormData(form),type=form.id;
 if(type==='org-group-form'){const name=String(values.get('groupName')||'').trim(),cabName=String(values.get('cabinetName')||'').trim();if(!name||!cabName)throw new Error('Renseignez le groupe et son premier cabinet.');orgCommit(()=>{if(organizationWorkspace.groups.length>=100||organizationWorkspace.cabinets.length>=500)throw new Error('La limite de groupes ou cabinets de la démonstration est atteinte.');if(organizationWorkspace.groups.some(g=>normalizedSearch(g.name)===normalizedSearch(name)))throw new Error('Un groupe porte déjà ce nom.');const gid=regId('group'),cid=regId('cabinet');organizationWorkspace.groups.push({id:gid,name,description:''});organizationWorkspace.cabinets.push({id:cid,groupId:gid,name:cabName,city:''});for(const roleId of ['group-admin','legal-manager'])organizationWorkspace.assignments.push({id:regId('assignment'),personId:'me',roleId,scope:'group',scopeId:gid,protected:roleId==='group-admin'});organizationWorkspace.context={groupId:gid,cabinetId:'all'};});orgResetFilters();}
 if(type==='org-cabinet-form'){const id=form.dataset.id;if(!orgCanManage('me',id||'all'))throw new Error('Vous ne pouvez pas modifier ce cabinet.');orgCommit(()=>{const name=String(values.get('cabinetName')||'').trim();if(!name)throw new Error('Renseignez le nom du cabinet.');if(organizationWorkspace.cabinets.some(c=>c.groupId===orgGroup().id&&c.id!==id&&normalizedSearch(c.name)===normalizedSearch(name)))throw new Error('Un cabinet porte déjà ce nom dans ce groupe.');const row=orgCabinet(id);if(row){row.name=name;row.city=String(values.get('city')||'').trim();}else{if(organizationWorkspace.cabinets.length>=500)throw new Error('500 cabinets maximum dans la démonstration.');organizationWorkspace.cabinets.push({id:regId('cabinet'),groupId:orgGroup().id,name,city:String(values.get('city')||'').trim()});}});}
 if(type==='org-company-form'){orgReviewCompany(form);return;}
 if(type==='org-bulk-license-form'){orgReviewBulk(form);return;}
 if(type==='org-confirm-form'){const change=orgPendingChange;if(!change)throw new Error('Aucune modification à confirmer.');orgCommit(()=>{if(change.kind==='company'){if(!orgCanManageCompany(change.id)||JSON.stringify(orgLink(change.id))!==change.base)throw new Error('Le dossier a changé. Fermez et reprenez sa modification.');Object.assign(orgLink(change.id),change.next);organizationWorkspace.delegations=organizationWorkspace.delegations.filter(d=>!(d.companyId===change.id&&d.cabinetId===change.next.cabinetId));}else{for(const[id,base]of change.bases){if(!orgCanManageCompany(id)||JSON.stringify(orgLink(id))!==base)throw new Error('Une société a changé. Reprenez la sélection.');}for(const id of change.ids)orgLink(id).plan=change.plan;}});orgPendingChange=null;orgUI.selected.clear();}
 if(type==='org-share-form'){const id=form.dataset.id;if(!orgCanManageCompany(id))throw new Error('Vous ne pouvez pas partager ce dossier.');const selected=values.getAll('cabinet');orgCommit(()=>{const from=orgCabinet(orgLink(id).cabinetId);if(selected.some(cid=>orgCabinet(cid)?.groupId!==from.groupId||cid===from.id))throw new Error('Le partage doit rester dans ce groupe.');organizationWorkspace.delegations=organizationWorkspace.delegations.filter(d=>d.companyId!==id);for(const cid of selected)organizationWorkspace.delegations.push({id:regId('share'),companyId:id,cabinetId:cid,level:values.get('level-'+cid)==='write'?'write':'read'});});}
 if(type==='org-assignment-form'){let personId=String(values.get('personId')),role=orgRole(String(values.get('roleId'))),scope=role?.management==='group'?'group':role?.management==='cabinet'?'cabinet':String(values.get('scope')),scopeId=String(values.get('scopeId'));if(!role)throw new Error('Choisissez un rôle.');if(role.groupId&&role.groupId!==orgGroup().id)throw new Error('Ce rôle appartient à un autre groupe.');const groupId=scope==='group'?scopeId:scope==='cabinet'?orgCabinet(scopeId)?.groupId:orgEntryGroup(scopeId);if(groupId!==orgGroup().id||!orgCanManage('me',scope==='cabinet'?scopeId:scope==='company'?orgLink(scopeId)?.cabinetId:'all',groupId))throw new Error('Ce périmètre ne peut pas être administré depuis ce groupe.');orgCommit(()=>{if(personId==='new'){const name=String(values.get('personName')||'').trim(),email=String(values.get('personEmail')||'').trim().toLowerCase();if(!name||!email)throw new Error('Renseignez la personne et son e-mail.');const known=organizationWorkspace.people.find(p=>p.email.toLowerCase()===email);if(known)personId=known.id;else{if(organizationWorkspace.people.length>=2000)throw new Error('2 000 personnes maximum dans la démonstration.');personId=regId('person');organizationWorkspace.people.push({id:personId,name,email});}}if(!organizationWorkspace.people.some(p=>p.id===personId))throw new Error('Personne introuvable.');if(organizationWorkspace.assignments.some(a=>a.personId===personId&&a.roleId===role.id&&a.scope===scope&&a.scopeId===scopeId))throw new Error('Cette attribution existe déjà.');if(organizationWorkspace.assignments.length>=5000)throw new Error('5 000 attributions maximum dans la démonstration.');organizationWorkspace.assignments.push({id:regId('assignment'),personId,roleId:role.id,scope,scopeId,protected:false});});}
 if(type==='org-role-form'){const existing=orgRole(form.dataset.id);if(existing?.protected)throw new Error('Ce rôle est protégé.');if(existing?.groupId&&existing.groupId!==orgGroup().id)throw new Error('Ce rôle appartient à un autre groupe.');if(!orgCanManage('me','all'))throw new Error('Seul l’administrateur du groupe peut définir un rôle commun.');orgCommit(()=>{const name=String(values.get('roleName')||'').trim();if(!name)throw new Error('Nommez le rôle.');const permissions=Object.fromEntries(ORG_FEATURES.map(([id])=>[id,['read','write'].includes(values.get('permission-'+id))?values.get('permission-'+id):'none']));if(existing){existing.name=name;existing.permissions=permissions;}else{if(organizationWorkspace.roles.filter(r=>!r.protected).length>=100)throw new Error('100 rôles personnalisés maximum dans la démonstration.');organizationWorkspace.roles.push({id:regId('role'),groupId:orgGroup().id,name,management:'none',permissions,protected:false});}});}
 if(type==='org-remove-assignment-form'){const a=organizationWorkspace.assignments.find(a=>a.id===form.dataset.id);if(!a||a.protected||!orgCanManage('me',a.scope==='cabinet'?a.scopeId:a.scope==='company'?orgLink(a.scopeId)?.cabinetId:'all',orgScopeGroup(a)))throw new Error('Cette attribution ne peut pas être retirée.');orgCommit(()=>{organizationWorkspace.assignments=organizationWorkspace.assignments.filter(r=>r.id!==a.id);});}
 $('#modal').close();render();toast('Les modifications de l’organisation ont été enregistrées.');
}
document.addEventListener('submit',event=>{if(!event.target.id.startsWith('org-'))return;event.preventDefault();try{if(event.target.reportValidity())orgSaveForm(event.target);}catch(error){const target=$('#org-form-status');if(target)target.textContent=error.message;else toast(error.message);}});
document.addEventListener('click',event=>{
 const page=event.target.closest('[data-collection-page]');if(page){const name=page.dataset.collection;if(name==='org-portfolio'){orgUI.page=Number(page.dataset.collectionPage);refreshOrgPortfolio();}if(name==='org-people'){orgUI.peoplePage=Number(page.dataset.collectionPage);$('#org-assignment-rows').innerHTML=orgAssignmentRows();$('#org-people-pagination').innerHTML=orgPeoplePagination();}if(name==='org-picker'){orgUI.pickerPage=Number(page.dataset.collectionPage);refreshOrgPicker();}}
 const button=event.target.closest('[data-org-action]');if(!button||button.disabled)return;const {orgAction:action,id}=button.dataset;
 if(action==='group-new')orgOpenGroupForm();if(action==='cabinet-new')orgOpenCabinetForm();if(action==='cabinet-edit')orgOpenCabinetForm(id);if(action==='cabinet-open')changeOrgContext(orgGroup().id,id);if(action==='company-settings')orgOpenCompanySettings(id);if(action==='company-share')orgOpenShare(id);if(action==='assignment-new')orgOpenAssignment();if(action==='role-new')orgOpenRole();if(action==='role-view')orgOpenRole(id);if(action==='bulk-license')orgOpenBulkLicense();if(action==='clear-selection'){orgUI.selected.clear();refreshOrgPortfolio();}if(action==='select-page'){const all=orgFilteredCompanies();all.slice((orgUI.page-1)*10,orgUI.page*10).filter(e=>orgCanManageCompany(e.id)).forEach(e=>orgUI.selected.add(e.id));refreshOrgPortfolio();}if(action==='assignment-remove'){const a=organizationWorkspace.assignments.find(a=>a.id===id);if(a&&!a.protected)orgModal('Retirer cette attribution',`<p class="modal-description">${escapeHTML(organizationWorkspace.people.find(p=>p.id===a.personId)?.name||'')} · ${escapeHTML(orgRole(a.roleId)?.name||'')} · ${escapeHTML(orgScopeLabel(a))}</p><p>Les autres attributions de cette personne sont conservées.</p><form id="org-remove-assignment-form" data-id="${id}">${orgFormActions('Retirer l’attribution')}</form>`);}
});
document.addEventListener('input',event=>{if(event.target.id==='org-query'){orgUI.query=event.target.value;orgUI.page=1;refreshOrgPortfolio();}if(event.target.id==='org-picker-query'){orgUI.pickerQuery=event.target.value;orgUI.pickerPage=1;refreshOrgPicker();}if(event.target.id==='org-person-query'){orgUI.peopleQuery=event.target.value;orgUI.peoplePage=1;$('#org-assignment-rows').innerHTML=orgAssignmentRows();$('#org-people-pagination').innerHTML=orgPeoplePagination();}});
document.addEventListener('change',event=>{
 const id=event.target.id;
 if(id==='org-group-select')changeOrgContext(event.target.value);if(id==='org-cabinet-select')changeOrgContext(orgGroup().id,event.target.value);
 if(id==='org-dashboard-plan'||id==='org-dashboard-responsible'){orgUI[id==='org-dashboard-plan'?'plan':'responsible']=event.target.value;orgUI.page=1;if(activeTab==='espace')updateCompanyFilter();else refreshOrgPortfolio();}
 if(event.target.matches('[data-org-select]')){const id=event.target.dataset.orgSelect;if(event.target.checked&&orgCanManageCompany(id))orgUI.selected.add(id);else orgUI.selected.delete(id);$('#org-bulk').innerHTML=orgBulkHTML();}
 if(id==='org-assignment-person'){const area=$('[data-org-new-person]');area.hidden=event.target.value!=='new';area.disabled=area.hidden;}
 if(id==='org-assignment-role'||id==='org-assignment-scope')orgRefreshAssignmentTargets();
 if(id.startsWith('org-inspector-')){orgUI.inspectorPerson=$('#org-inspector-person').value;orgUI.inspectorCompany=$('#org-inspector-company').value;orgUI.inspectorFeature=$('#org-inspector-feature').value;$('#org-inspector-result').innerHTML=orgInspectorHTML();}
});
function orgCompanyAdministrationContext(){const link=orgLink(currentCompany.id),cab=orgCabinet(link?.cabinetId);return `<div class="org-company-admin-link"><span>${escapeHTML(cab?.name||'Cabinet à définir')} · Licence ${orgPlan(link?.plan).name}<br>Les rôles du groupe et du cabinet se gèrent dans l’organisation ; les rôles propres à cette société restent ici.</span><a href="organisation.html#organisation/people">Équipes et périmètres ${icon('arrow')}</a></div>`;}
function orgCurrentViewFeature(){if(activeTab==='administration')return location.hash==='#administration/preferences'?'preferences':'utilisateurs';return{societe:'societe',associes:'associes',titres:'titres',decisions:'decisions',personnel:'personnel',documents:'documents',procedures:'procedures'}[activeTab];}
function orgApplyCompanyViewPolicy(){
 const heading=$('.page-heading>.button');if(heading)heading.disabled=false;const feature=orgCurrentViewFeature();if(!feature)return;
 const result=orgEffectiveAccess('me',currentCompany.id,feature);
 if(result.level==='none'){if(heading)heading.disabled=true;$('#view').innerHTML=`<section class="panel org-blocked"><span class="badge">${result.roleLevel==='none'?'Accès non attribué':'Fonctionnalité hors licence'}</span><h2>${result.roleLevel==='none'?'Un rôle est nécessaire pour ouvrir cet espace.':'La licence de cette société ne donne pas accès à cet espace.'}</h2><p>${escapeHTML(company.name)} · ${orgPlan(orgLink(currentCompany.id)?.plan).name}. Le rattachement à un cabinet ne remplace pas l’attribution d’un rôle juridique.</p><a class="button" href="organisation.html#organisation/roles">Vérifier les accès</a><button class="button button-primary" data-org-action="company-settings" data-id="${currentCompany.id}">Gérer la licence de cette société</button></section>`;return;}
 if(result.level==='read'){if(heading&&orgIsWriteControl(heading))heading.disabled=true;
  const notice=document.createElement('p');notice.className='org-readonly-note';notice.textContent='Lecture seule dans ce périmètre : les permissions et la licence de cette société limitent les modifications.';$('#view').prepend(notice);
  for(const control of $$('#view button'))if(orgIsWriteControl(control)){control.disabled=true;control.title='Cette action nécessite un droit d’écriture et une licence adaptée.';}
 }
 if(activeTab==='decisions'&&orgEffectiveAccess('me',currentCompany.id,'custom-decisions').level!=='write')for(const control of $$('#view [data-register-action="decision-register-add"],#view [data-register-action="decision-register-edit"]')){control.disabled=true;control.title='Les registres sur mesure nécessitent une licence et un rôle adaptés.';}
}
function orgIsWriteControl(control){const action=control.dataset.action,register=control.dataset.registerAction,access=control.dataset.accessAction;if(action)return ['edit','capital-setup','edit-capital','add-associate','upload','associate-invite','associate-account-settings','accounts','announcement','new-procedure'].includes(action);if(register)return !['archive-html','archive-open','archive-zip','file-download','filters-reset','filters-toggle','movement-csv','person-documents','personnel-csv','project-download','pv-details','pv-file','register-help','staff-sort','decision-select'].includes(register);if(access)return !['person-rights','role-view','tab'].includes(access);return control.hasAttribute('data-setting')||control.hasAttribute('data-associate-edit')||control.hasAttribute('data-operation-action')&&control.dataset.operationAction==='edit';}
// Front-end guard only; does not claim to protect data without a server.
document.addEventListener('click',event=>{const control=event.target.closest('#view button,.page-heading button,#modal button');if(!control||control.disabled||!orgCurrentViewFeature()||!orgIsWriteControl(control))return;const feature=control.dataset.action==='accounts'?'depot':control.dataset.action==='announcement'?'annonces':orgCurrentViewFeature();if(orgEffectiveAccess('me',currentCompany.id,feature).level!=='write'){event.preventDefault();event.stopImmediatePropagation();toast('Cette action nécessite un rôle et une licence autorisant l’écriture.');}},true);
